import { test, expect } from '@playwright/test';

test('locators in priority order', async ({ page }) => {
  await page.goto('/login');
  await expect(page.getByRole('heading', { name: 'Sign in' })).toBeVisible();   // role + name
  await page.getByLabel('Email').fill('qa@example.com');                        // form label
  await expect(page.getByText('Practice account')).toBeVisible();              // visible text

  await page.goto('/dashboard');
  // redirected to login, because we are not signed in:
  await expect(page.getByRole('alert')).toHaveText('Please sign in first');
});

test('chaining and filtering', async ({ page }) => {
  await page.goto('/products');
  const rows = page.getByRole('row').filter({ has: page.getByRole('cell') });
  await expect(rows).toHaveCount(12);
  await expect(rows.filter({ hasText: 'Cheddar' })).toContainText('$9.90');
});
